mapper.update:
UPDATE approval_document_step
   SET status = #{newStatus},
       acted_by_user_id = #{actedByUserId},
       acted_at = NOW(),
       comment = #{comment}
 WHERE step_id = #{stepId}
   AND document_id = #{documentId}
   AND status = 'PENDING'

UPDATE approval_document
   SET status = #{newStatus},
       withdrawn_at = CASE WHEN #{newStatus} = 'WITHDRAWN' THEN #{now} ELSE withdrawn_at END,
       canceled_at  = CASE WHEN #{newStatus} = 'CANCELED'  THEN #{now} ELSE canceled_at END,
       updated_at = NOW()
 WHERE document_id = #{documentId}
   AND tenant_id = #{tenantId}
   AND requester_user_id = #{requesterUserId}
   AND status = #{expectedStatus}

mapper.sql:
d.tenant_id = #{tenantId}


   AND d.requester_user_id = #{userId}


   AND d.status = 'IN_PROGRESS'
   AND EXISTS (
     SELECT 1
       FROM approval_document_step s
       JOIN users u ON u.user_id = #{userId}
      WHERE s.document_id = d.document_id
        AND s.status = 'PENDING'
        AND s.step_order = d.current_step_order
        AND (
          (s.target_department_type = 'USER' AND s.target_user_id = #{userId})
          OR (
            s.target_department_type != 'USER'
            AND (s.target_department_id IS NULL OR s.target_department_id = u.org_id)
            AND (s.target_role_key IS NULL OR s.target_role_key = u.role_key)
          )
        )
   )


   AND EXISTS (
     SELECT 1 FROM approval_document_step s2
      WHERE s2.document_id = d.document_id
        AND s2.acted_by_user_id = #{userId}
   )



 AND d.approval_code = #{approvalCode}


 AND d.status = #{status}


 AND (d.title ILIKE '%' || #{keyword} || '%' OR d.document_no ILIKE '%' || #{keyword} || '%')


 AND d.requested_at >= #{fromDate}


 AND d.requested_at <= #{toDate}

mapper.select:
SELECT COUNT(*)
  FROM approval_document_step s
  JOIN users u ON u.user_id = #{userId}
 WHERE s.step_id = #{stepId}
   AND s.status = 'PENDING'
   AND (
     (s.target_department_type = 'USER' AND s.target_user_id = #{userId})
     OR (
       s.target_department_type != 'USER'
       AND (s.target_department_id IS NULL OR s.target_department_id = u.org_id)
       AND (s.target_role_key IS NULL OR s.target_role_key = u.role_key)
     )
   )

