SELECT COALESCE(MAX(
  CAST(split_part(document_no, '-', 4) AS INTEGER)
), 0)
  FROM approval_document
 WHERE tenant_id = #{tenantId}
   AND document_no LIKE 'AP-' || #{tenantId} || '-' || #{yyyymm} || '-%'
